<?php
namespace App\Models;use App\Casts\DateOnly;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\HasMany;
/** Provides performance review cycle behavior within the WorkIntel application. */ class PerformanceReviewCycle extends Model{protected $fillable=['uuid','workspace_id','name','review_type','status','start_date','end_date','self_review_enabled','manager_review_enabled','calibration_enabled','questions','created_by'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['start_date'=>DateOnly::class,'end_date'=>DateOnly::class,'self_review_enabled'=>'boolean','manager_review_enabled'=>'boolean','calibration_enabled'=>'boolean','questions'=>'array'];}/** Handles the reviews operation for the current WorkIntel workflow. */ public function reviews():HasMany{return $this->hasMany(PerformanceReview::class,'cycle_id');}}
